def make_norm(config):
    if config.normalization == "layer":
        return nn.LayerNorm(config.width)
    if config.normalization == "rms":
        return RMSNorm(config.width)
    return nn.Identity()

def fit(cls, documents, count=32):
    if not documents or not any(documents) or not 0 <= count <= 256:
        raise ValueError("Need training text and 0–256 merges.")
    sequences = [[b + 3 for b in text.encode("utf-8")] for text in documents]
    merges = []
    for _ in range(count):
        counts = Counter(pair for sequence in sequences for pair in zip(sequence, sequence[1:]))
        if not counts:
            break
        # Stable tie-breaking, and no pairs spanning documents.
        pair = min(counts, key=lambda p: (-counts[p], p))
        if counts[pair] < 2:
            break
        sequences = [cls.replace(s, pair, 259 + len(merges)) for s in sequences]
        merges.append(pair)
    return cls(merges)

def select_training_data(rows, fraction):
    train_rows = [r for r in rows if r["split"] == "train"]
    selected = {r["id"] for r in train_rows[:max(1, int(len(train_rows)*fraction))]}
    return [r for r in rows if r["split"] != "train" or r["id"] in selected]

def choose_device(requested="auto"):
    if requested not in {"auto", "cpu", "cuda", "mps"}:
        raise ValueError("Unknown device; choose auto, cpu, cuda or mps.")
    available = available_devices()
    if requested != "auto":
        if not available[requested]:
            raise ValueError(f"{requested.upper()} is unavailable in this Python installation. Choose auto or cpu.")
        error = probe(requested)
        if error:
            raise ValueError(f"{requested.upper()} failed its basic training check: {error}")
        return requested
    for device in ("cuda", "mps", "cpu"):
        if available[device] and probe(device) is None:
            return device
    raise ValueError("No working local training device was found.")

