def encode_text(texts, train, max_tokens, vocabulary_limit):
    counts = Counter(token for i in train for token in word_tokens(str(texts[i])))
    words = sorted(counts, key=lambda word: (-counts[word], word))[:vocabulary_limit-2]
    vocabulary = {word: i + 2 for i, word in enumerate(words)}
    x = np.zeros((len(texts), max_tokens), dtype=np.int64)
    for i, text in enumerate(texts):
        ids = [vocabulary.get(t, 1) for t in word_tokens(str(text))[:max_tokens]] or [1]
        x[i, :len(ids)] = ids
    return x, vocabulary

def sms_rows(archive):
    texts, labels, seen = [], [], {}
    for line in member(archive, "SMSSpamCollection", 2_000_000).decode("utf-8-sig").splitlines():
        label, text = line.split("\t", 1)
        if label not in {"ham", "spam"} or not text.strip(): raise ValueError("Invalid SMS record.")
        key = " ".join(text.casefold().split())
        if key in seen:
            if seen[key] != label: raise ValueError("Conflicting labels on identical SMS text.")
            continue
        seen[key] = label
        texts.append(text); labels.append(int(label == "spam"))
    if len(texts) < 20 or len(set(labels)) != 2: raise ValueError("Insufficient SMS classes/examples.")
    return np.asarray(texts), np.asarray(labels, dtype=np.int64)

def har_rows(archive):
    # UCI sometimes distributes a fixed nested zip beside the dataset's papers.
    if "UCI HAR Dataset.zip" in archive.namelist():
        with zipfile.ZipFile(io.BytesIO(member(archive, "UCI HAR Dataset.zip", 90_000_000))) as inner:
            return har_rows(inner)
    arrays, labels, subjects, original = [], [], [], []
    channels = [f"{kind}_{axis}" for kind in ["body_acc", "body_gyro", "total_acc"] for axis in "xyz"]
    for split in ["train", "test"]:
        prefix = "UCI HAR Dataset/" + split + "/"
        signals = [np.loadtxt(io.BytesIO(member(archive, prefix + "Inertial Signals/" + c + "_" + split + ".txt", 20_000_000)), dtype=np.float32, ndmin=2) for c in channels]
        x = np.stack(signals, axis=-1)
        y = np.loadtxt(io.BytesIO(member(archive, prefix + "y_" + split + ".txt", 100_000)), dtype=np.int64, ndmin=1) - 1
        people = np.loadtxt(io.BytesIO(member(archive, prefix + "subject_" + split + ".txt", 100_000)), dtype=np.int64, ndmin=1)
        if x.shape != (len(y), 128, 9) or len(people) != len(y) or not np.isfinite(x).all() or (y < 0).any() or (y > 5).any():
            raise ValueError("Invalid HAR sequence shapes, values or labels.")
        arrays.append(x); labels.append(y); subjects.append(people); original.extend([split] * len(y))
    if set(subjects[0]) & set(subjects[1]): raise ValueError("HAR original splits share participants.")
    return np.concatenate(arrays), np.concatenate(labels), np.concatenate(subjects), np.asarray(original), channels

def bike_rows(archive):
    rows = list(csv.DictReader(io.StringIO(member(archive, "hour.csv", 3_000_000).decode("utf-8-sig"))))
    values = {}
    for row in rows:
        stamp = datetime.strptime(row["dteday"], "%Y-%m-%d") + timedelta(hours=int(row["hr"]))
        count = float(row["cnt"])
        if not 0 <= int(row["hr"]) <= 23 or count < 0 or not np.isfinite(count) or stamp in values:
            raise ValueError("Invalid or duplicate Bike Sharing hour.")
        values[stamp] = count
    times, histories, targets = [], [], []
    for stamp in sorted(values):
        past = [stamp - timedelta(hours=i) for i in range(96, 0, -1)]
        # Fixed target cohort across every lookback; gaps are not silently compressed.
        if all(t in values for t in past):
            times.append(stamp.isoformat()); histories.append([values[t] for t in past]); targets.append(values[stamp])
    if len(times) < 30: raise ValueError("Not enough complete 96-hour histories.")
    return np.asarray(histories, dtype=np.float32), np.asarray(targets, dtype=np.float32), times

class SequencePredictor(nn.Module):
    """Turn tokens, sensor steps or image rows into one class/number per example."""
    def __init__(self, name, p, outputs, spec, image_shape=None):
        super().__init__()
        self.name, self.spec, self.image_shape = name, spec, image_shape
        width, layers, dropout = p.get("width", 64), p.get("layers", 1), p["dropout"]
        self.text = spec["kind"] == "text"
        if self.text:
            inputs = p["embedding_dim"]
            self.embedding = nn.Embedding(spec["vocabulary_size"], inputs, padding_idx=0)
            max_length = spec["sequence_shape"][0]
        else:
            max_length, inputs = spec["sequence_shape"]
        self.drop = nn.Dropout(dropout)
        self.bidirectional = name.startswith("bi")
        if name in {"rnn", "birnn", "lstm", "bilstm", "gru", "bigru"}:
            cell = nn.LSTM if "lstm" in name else nn.GRU if "gru" in name else nn.RNN
            self.encoder = cell(inputs, width, num_layers=layers, batch_first=True,
                                bidirectional=self.bidirectional, dropout=dropout if layers > 1 else 0)
            hidden = width * (2 if self.bidirectional else 1)
        elif name == "embedding_mean":
            hidden = inputs
        else:
            self.input_projection = nn.Linear(inputs, width)
            hidden = width
            if name == "transformer_encoder":
                self.position = nn.Parameter(torch.zeros(1, max_length, width)) if p["positions"] else None
                if self.position is not None: nn.init.normal_(self.position, std=.02)
                self.blocks = nn.ModuleList([EncoderBlock(width, p["heads"], dropout) for _ in range(layers)])
            elif name == "tcn":
                self.blocks = nn.ModuleList([TemporalBlock(width, p["kernel_size"], 2**i, dropout) for i in range(layers)])
            else:
                self.blocks = nn.ModuleList([nn.Conv1d(width, width, p["kernel_size"], padding=p["kernel_size"]//2) for _ in range(layers)])
        self.head = nn.Linear(hidden, outputs)

    def forward(self, flat):
        if self.text:
            valid = flat != 0
            lengths = valid.sum(1).clamp_min(1)
            x = self.embedding(flat.long())
        else:
            if self.image_shape:
                # One time step is one horizontal image row, across all channels.
                x = flat.reshape(-1, *self.image_shape).permute(0, 2, 1, 3).flatten(2)
            else:
                x = flat.reshape(-1, *self.spec["sequence_shape"])
            valid = torch.ones(x.shape[:2], dtype=torch.bool, device=x.device)
            lengths = valid.sum(1)
        if self.name in {"rnn", "birnn", "lstm", "bilstm", "gru", "bigru"}:
            packed = pack_padded_sequence(x, lengths.cpu(), batch_first=True, enforce_sorted=False)
            _, state = self.encoder(packed)
            hidden = state[0] if isinstance(state, tuple) else state
            # Last layer's forward AND backward final states, not last output row.
            pooled = torch.cat([hidden[-2], hidden[-1]], dim=-1) if self.bidirectional else hidden[-1]
        elif self.name == "embedding_mean":
            pooled = (x * valid.unsqueeze(-1)).sum(1) / lengths.unsqueeze(-1)
        else:
            x = self.input_projection(x) * valid.unsqueeze(-1)
            if self.name == "transformer_encoder":
                if self.position is not None: x = (x + self.position[:, :x.shape[1]]) * valid.unsqueeze(-1)
                for block in self.blocks: x = block(x, valid)
            else:
                x = x.transpose(1, 2)
                for block in self.blocks:
                    x = block(x, valid) if self.name == "tcn" else self.drop(torch.relu(block(x))) * valid[:, None, :]
                x = x.transpose(1, 2)
            # Regression reads the final history state; classification pools valid steps.
            pooled = x[torch.arange(len(x), device=x.device), lengths - 1] if self.spec.get("forecast") else (x * valid.unsqueeze(-1)).sum(1) / lengths.unsqueeze(-1)
        return self.head(self.drop(pooled))

class TemporalBlock(nn.Module):
    """Two causal, dilated convolutions plus an identity shortcut."""
    def __init__(self, width, kernel, dilation, dropout):
        super().__init__()
        self.padding = (kernel - 1) * dilation
        self.convs = nn.ModuleList([nn.Conv1d(width, width, kernel, dilation=dilation) for _ in range(2)])
        self.drop = nn.Dropout(dropout)

    def forward(self, x, valid):
        original = x
        mask = valid[:, None, :]
        for conv in self.convs:
            x = self.drop(torch.relu(conv(nn.functional.pad(x, (self.padding, 0))))) * mask
        return torch.relu(x + original) * mask

class TinyViT(nn.Module):
    """Train a small mean-pooled ViT from scratch, not a pretrained foundation model."""
    def __init__(self, p, outputs, image_shape):
        super().__init__()
        channels, height, width = image_shape
        patch, hidden = p["patch_size"], p["width"]
        if height % patch or width % patch: raise ValueError("Patch size must divide both image dimensions.")
        self.image_shape = image_shape
        self.patches = nn.Conv2d(channels, hidden, patch, stride=patch)
        self.position = nn.Parameter(torch.zeros(1, (height//patch)*(width//patch), hidden)) if p["positions"] else None
        if self.position is not None: nn.init.normal_(self.position, std=.02)
        self.blocks = nn.ModuleList([EncoderBlock(hidden, p["heads"], p["dropout"]) for _ in range(p["layers"])])
        self.norm, self.head = nn.LayerNorm(hidden), nn.Linear(hidden, outputs)

    def forward(self, flat):
        x = self.patches(flat.reshape(-1, *self.image_shape)).flatten(2).transpose(1, 2)
        if self.position is not None: x = x + self.position
        valid = torch.ones(x.shape[:2], dtype=torch.bool, device=x.device)
        for block in self.blocks: x = block(x, valid)
        return self.head(self.norm(x).mean(1))

def estimator(model, task, p):
    regression = task == "regression"
    if model == "dummy": return DummyRegressor() if regression else DummyClassifier(strategy="most_frequent")
    if model in {"logistic", "tfidf_logistic"}: return LogisticRegression(C=p["C"], max_iter=1500, random_state=p["seed"])
    if model == "tfidf_nb": return MultinomialNB(alpha=p["alpha"])
    if model == "ridge": return Ridge(alpha=p["strength"])
    if model == "lasso": return Lasso(alpha=p["strength"], max_iter=3000)
    if model == "elastic": return ElasticNet(alpha=p["strength"], l1_ratio=p["l1_ratio"], max_iter=3000)
    if model == "knn": return KNeighborsClassifier(n_neighbors=p["neighbors"], weights=p["neighbor_weights"], n_jobs=1)
    if model == "svm":
        args = dict(C=p["C"], kernel=p["kernel"], gamma=p["gamma"], cache_size=256)
        return SVR(**args, epsilon=p["epsilon"]) if regression else SVC(**args, probability=False, random_state=p["seed"])
    if model == "naive_bayes": return GaussianNB(var_smoothing=p["smoothing"])
    if model in {"tree", "forest"}:
        cls = {("tree", False): DecisionTreeClassifier, ("tree", True): DecisionTreeRegressor,
               ("forest", False): RandomForestClassifier, ("forest", True): RandomForestRegressor}[model, regression]
        args = dict(max_depth=p["depth"], min_samples_leaf=p["leaf"], random_state=p["seed"])
        if model == "forest": args.update(n_estimators=p["trees"], n_jobs=1)
        return cls(**args)
    if model == "boost":
        cls = HistGradientBoostingRegressor if regression else HistGradientBoostingClassifier
        return cls(max_iter=p["rounds"], learning_rate=p["boost_rate"], max_depth=p["depth"], min_samples_leaf=p["leaf"], early_stopping=False, random_state=p["seed"])
    if model == "kmeans": return KMeans(n_clusters=p["clusters"], n_init=10, random_state=p["seed"])
    if model == "gmm": return GaussianMixture(n_components=p["clusters"], reg_covar=1e-5, random_state=p["seed"])
    if model == "dbscan": return DBSCAN(eps=p["radius"], min_samples=p["min_samples"], n_jobs=1)
    if model == "pca": return PCA(n_components=p["components"], svd_solver="full")
    if model == "isolation": return IsolationForest(n_estimators=p["trees"], contamination=p["contamination"], n_jobs=1, random_state=p["seed"])
    raise ValueError("No classical estimator for this method.")

def network(name, p, features, outputs, image_shape, input_spec=None):
    import torch
    from torch import nn
    from .sequence_models import SEQUENCE_MODELS, SequencePredictor, TinyViT
    if name == "vit": return TinyViT(p, outputs, image_shape)
    if name in SEQUENCE_MODELS:
        if input_spec is None and image_shape:
            c, h, w = image_shape
            input_spec = {"kind":"image", "sequence_shape":[h, c*w]}
        if not input_spec or input_spec["kind"] == "table": raise ValueError("Sequence models require ordered steps, text or image rows.")
        return SequencePredictor(name, p, outputs, input_spec, image_shape)
    activation = {"relu": nn.ReLU, "gelu": nn.GELU, "tanh": nn.Tanh}[p.get("activation", "relu")]
    width = p.get("width", 64)
    def norm(n, spatial=False):
        kind = p.get("normalization", "none")
        if kind == "batch": return nn.BatchNorm2d(n) if spatial else nn.BatchNorm1d(n)
        if kind == "layer": return nn.GroupNorm(1, n) if spatial else nn.LayerNorm(n)
        return nn.Identity()
    if name == "linear_head": return nn.Sequential(nn.Flatten(), nn.Linear(features, outputs))
    if name == "mlp":
        layers = [nn.Flatten()]; previous = features
        for _ in range(p["layers"]):
            layers.extend([nn.Linear(previous, width), norm(width), activation(), nn.Dropout(p["dropout"])])
            previous = width
        return nn.Sequential(*layers, nn.Linear(width, outputs))
    if name == "autoencoder":
        return nn.Sequential(nn.Flatten(), nn.Linear(features, width), activation(), nn.Linear(width, max(2, width // 4)), activation(), nn.Linear(max(2, width // 4), width), activation(), nn.Linear(width, features), nn.Sigmoid())
    if name == "residual_mlp":
        class DenseResidual(nn.Module):
            def __init__(self):
                super().__init__()
                self.path = nn.Sequential(nn.Linear(width, width), norm(width), activation(), nn.Dropout(p["dropout"]), nn.Linear(width, width), norm(width))
                self.act = activation()
            def forward(self, x): return self.act(x + self.path(x))
        return nn.Sequential(nn.Flatten(), nn.Linear(features, width), activation(), *[DenseResidual() for _ in range(p["layers"])], nn.Linear(width, outputs))
    if not image_shape: raise ValueError("Convolution requires spatial images.")
    channels = image_shape[0]
    if name == "conv_autoencoder":
        latent = max(2, width // 16)
        return nn.Sequential(nn.Unflatten(1, tuple(image_shape)), nn.Conv2d(channels, width, 3, stride=2, padding=1), activation(),
                             nn.Conv2d(width, latent, 3, stride=2, padding=1), activation(),
                             nn.ConvTranspose2d(latent, width, 4, stride=2, padding=1), activation(),
                             nn.ConvTranspose2d(width, channels, 4, stride=2, padding=1), nn.Sigmoid(), nn.Flatten())
    class Residual(nn.Module):
        def __init__(self, channels):
            super().__init__()
            self.path = nn.Sequential(nn.Conv2d(channels, channels, 3, padding=1), norm(channels, True), activation(), nn.Conv2d(channels, channels, 3, padding=1), norm(channels, True))
            self.act = activation()
        def forward(self, x): return self.act(x + self.path(x))
    side = image_shape[-1] // 4
    kernel = 5 if name == "lenet" else 3
    blocks = [nn.Unflatten(1, tuple(image_shape)), nn.Conv2d(channels, width, kernel, padding=kernel//2), norm(width, True), activation()]
    if name == "residual": blocks.append(Residual(width))
    blocks.extend([nn.MaxPool2d(2), nn.Conv2d(width, width * 2, kernel, padding=kernel//2), norm(width * 2, True), activation()])
    if name == "residual": blocks.append(Residual(width * 2))
    blocks.extend([nn.MaxPool2d(2), nn.Flatten(), nn.Dropout(p["dropout"])])
    if name == "lenet": blocks.extend([nn.Linear(width * 2 * side * side, 84), activation(), nn.Linear(84, outputs)])
    else: blocks.append(nn.Linear(width * 2 * side * side, outputs))
    return nn.Sequential(*blocks)

def _classical(settings, data, directory, update):
    p = settings["controls"]; task = settings["task"]; name = settings["model"]
    transform = {"none": None, "standard": StandardScaler(), "robust": RobustScaler()}[p.get("scaling", "none")]
    train = data["indices"]["train"]; x, y = data["x"], data["y"]
    update(phase="Fitting training-only preprocessing and estimator")
    model = estimator(name, task, p)
    pipeline = Pipeline([("scale", transform or "passthrough"), ("model", model)])
    if name in {"tfidf_logistic", "tfidf_nb"}:
        from .sequence_data import word_tokens
        x = data["texts"]
        transform = TfidfVectorizer(tokenizer=word_tokens, token_pattern=None, lowercase=False,
                                    max_features=p["vocab_size"], ngram_range=(1, p["ngrams"]))
        pipeline = Pipeline([("tfidf", transform), ("model", model)])
    with warnings.catch_warnings(record=True) as caught, threadpool_limits(limits=2):
        warnings.simplefilter("always")
        pipeline.fit(x[train], y[train] if task in {"classification", "regression"} else None)
        if task in {"classification", "regression"}:
            outputs = {}
            update(phase="Evaluating fixed development and test splits")
            for split in ["train", "dev", "test"]:
                values = x[data["indices"][split]]
                prob = pipeline.predict_proba(values) if hasattr(model, "predict_proba") and task == "classification" else None
                outputs[split] = (pipeline.predict(values), prob)
            result = {"predictions": _prediction_artifact(data, outputs, task)}
        else:
            scaled = pipeline[:-1].transform(x[train])
            reference = y[train]
            if name == "pca":
                result = {"representation": {"explained_variance_ratio": model.explained_variance_ratio_.tolist(), "projection": model.transform(scaled[:500])[:, :2].tolist(), "labels": reference[:500].tolist(), "reconstruction_mse": {}}}
                for split, ids in data["indices"].items():
                    z = pipeline[:-1].transform(x[ids]); restored = model.inverse_transform(model.transform(z))
                    result["representation"]["reconstruction_mse"][split] = float(np.mean((z - restored)**2))
                result["representation"]["units"] = "Squared error in the chosen preprocessed feature units; not necessarily pixel units."
            elif name == "isolation":
                result = {"anomaly": {}}
                for split, ids in data["indices"].items():
                    score = -pipeline.decision_function(x[ids]); flagged = pipeline.predict(x[ids]) == -1
                    result["anomaly"][split] = {"roc_auc": float(metrics.roc_auc_score(y[ids] == -1, score)), "flagged_fraction": float(flagged.mean())}
            else:
                assignments = model.labels_ if name == "dbscan" else model.predict(scaled)
                unique = np.unique(assignments); meaningful = assignments != -1
                silhouette = None
                if meaningful.sum() > 2 and 1 < len(np.unique(assignments[meaningful])) < meaningful.sum():
                    silhouette = float(metrics.silhouette_score(scaled[meaningful], assignments[meaningful], sample_size=min(1000, meaningful.sum()), random_state=11))
                projection = PCA(n_components=2).fit_transform(scaled) if scaled.shape[1] > 2 else scaled
                result = {"clustering": {"fit_silhouette_excluding_noise": silhouette, "fit_adjusted_rand_reference": float(metrics.adjusted_rand_score(reference, assignments)), "noise_fraction": float(np.mean(assignments == -1)), "groups_excluding_noise": int(sum(k != -1 for k in unique)), "projection": projection[:500].tolist(), "assignments": assignments[:500].tolist(), "note": "Fitting-set geometry and reference-label diagnostics, not supervised test accuracy. Labels were withheld from fitting; a 2D projection can hide distances."}}
                if name != "dbscan":
                    result["clustering"]["test_adjusted_rand_reference"] = float(metrics.adjusted_rand_score(y[data["indices"]["test"]], pipeline.predict(x[data["indices"]["test"]])) )
        result["warnings"] = list(dict.fromkeys(str(w.message) for w in caught))
    # Private, locally generated persistence only. Never loaded through a web request.
    import joblib
    joblib.dump(pipeline, directory / "estimator.joblib", compress=3)
    result["estimator_parameters"]=model.get_params(deep=False)
    if name in {"tfidf_logistic", "tfidf_nb"}:
        result["fitted_preprocessing"] = {"kind":"training-only TF-IDF", "features":len(transform.vocabulary_), "vocabulary":{k:int(v) for k,v in transform.vocabulary_.items()}}
    else:
        result["fitted_preprocessing"]={"kind":p["scaling"],"center":None if transform is None else getattr(transform,"mean_",getattr(transform,"center_",np.array([]))).tolist(),"scale":None if transform is None else transform.scale_.tolist()}
    result["persistence_note"] = "Trusted local sklearn/joblib artifact. Pickle-based files can execute code when loaded; never load a file from an untrusted source. The web API does not deserialize it."
    if hasattr(model, "feature_importances_"):
        result["feature_importance"] = model.feature_importances_.tolist()
        result["importance_note"] = "Training impurity-based importance; correlated/high-cardinality features can distort this. Not a causal explanation."
    elif hasattr(model, "coef_"):
        result["coefficients"] = np.asarray(model.coef_).tolist()
        result["intercept"] = np.asarray(model.intercept_).tolist()
    return result

def fit(identifier, settings, root=RUNS, data_root=model_data.DATA):
    settings = validate(settings, data_root=data_root); directory = run_path(identifier, root)
    if directory.exists(): raise ValueError("Run already exists; completed runs are immutable.")
    directory.mkdir(parents=True)
    manifest = {"id": identifier, "status": "RUNNING", "started_at": datetime.now(timezone.utc).isoformat(), "settings": settings,
                "phase": "Loading and checking local data", "versions": {"python": platform.python_version(), "sklearn": sklearn.__version__, "numpy": np.__version__},
                "source_hashes": source_hashes()}
    started = time.monotonic()
    def update(**values):
        manifest.update(values); write_json(directory / "manifest.json", manifest)
    update()
    try:
        data = model_data.load(settings["dataset"], settings["controls"]["train_limit"], data_root, settings["controls"])
        write_json(directory / "data.json", data["info"]); write_json(directory / "splits.json", data["split_ids"])
        update(data_fingerprint=data["info"]["fingerprint"], split_fingerprint=data["info"]["split_fingerprint"])
        result = _classical(settings, data, directory, update) if settings["area"] == "ml" else _neural(settings, data, directory, update)
        task = settings["task"]
        if task in {"classification", "regression"}:
            baseline = DummyRegressor() if task == "regression" else DummyClassifier(strategy="most_frequent")
            ids = data["indices"]; baseline.fit(data["x"][ids["train"]], data["y"][ids["train"]])
            result["baseline"] = {split: scores(data["y"][rows], baseline.predict(data["x"][rows]), task, labels=np.unique(data["y"]) if task == "classification" else None) for split, rows in ids.items()}
            if "persistence" in data:
                result["persistence_baseline"] = {split:scores(data["y"][rows], data["persistence"][rows], task) for split, rows in ids.items()}
            # Deterministic, unedited test examples, including model errors when present.
            test = result["predictions"]["test"]; truth = np.array(test["truth"]); pred = np.array(test["prediction"])
            ranked = np.argsort(-np.abs(truth-pred)) if task == "regression" else np.concatenate([np.flatnonzero(truth != pred), np.flatnonzero(truth == pred)])
            result["examples"] = [{"row_id": int(ids["test"][i]), "truth": float(truth[i]), "prediction": float(pred[i]),
                                   "features": data["x"][ids["test"][i]].tolist()} for i in ranked[:12]]
            for example in result["examples"]:
                row = example["row_id"]
                if "texts" in data: example["text"] = str(data["texts"][row]); example.pop("features")
                if "subjects" in data: example["participant"] = int(data["subjects"][row])
                if "target_times" in data: example["target_time"] = data["target_times"][row]
        write_json(directory / "result.json", result)
        update(status="MEASURED", phase="Completed", elapsed_seconds=time.monotonic()-started, completed_at=datetime.now(timezone.utc).isoformat())
        seal(directory)
    except BaseException as exc:
        update(status="CANCELLED" if isinstance(exc, KeyboardInterrupt) else "FAILED", phase="Stopped", error=str(exc), elapsed_seconds=time.monotonic()-started)
        if not isinstance(exc, KeyboardInterrupt): raise
    return manifest

